package numeric;

public class Febonasi_series {
	 public static void main(String[] args) {
	        // TODO Auto-generated method stub
	        int a = 10;
	        int sum = 0;

	        // Loop to calculate the sum of numbers from 1 to 'a'
	        for (int i = 1; i <= a; i++) {
	            sum = sum + i;
	            System.out.print(sum + ",");
	        }
	    }
}
